mapper.select:
SELECT id, student_id, quiz_id, score, start_time, due_time, submitted_time,
       time_spent_seconds, status, error_reason, created_at, updated_at
FROM attempts
WHERE id = #{attemptId}
  AND student_id = #{studentId}

SELECT COUNT(*)
FROM attempts
WHERE student_id = #{studentId}
  AND quiz_id = #{quizId}
  AND status IN ('FINISHED', 'ERROR')

SELECT id, student_id, quiz_id, score, start_time, due_time, submitted_time,
       time_spent_seconds, status, error_reason, created_at, updated_at
FROM attempts
WHERE student_id = #{studentId}
  AND quiz_id = #{quizId}
ORDER BY created_at DESC
